    answer: `① 상거래 또는 증명에 사용하기 위한 목적으로 측정량을 결정하는 법정계량에 사용하는 측정기기로 계량에 관한 법률에 따른 법정계량기
② 관리업체가 자체적으로 설치한 계량기로 국가표준기본법에 따른 시험기관, 교정기관, 검사기관에 의하여 주기적인 정도검사를 받는 측정기기
③ 관리업체가 자체적으로 설치한 계량기이나, 주기적인 정도검사를 실시하지 않는 측정기기`,
    keywords: ["법정계량기", "상거래", "관리업체", "정도검사", "국가표준기본법"],
