    question: `A 건물의 옥상에 총 면적 900m²에 해당하는 조경사업을 실시하려고 할 경우의 온실가스 감축량(tCO₂-eq)을 구하시오. (단, 온실가스 감축량 원단위는 0.015t/m²이다.)`,
    answer: `온실가스 감축량 = 옥상 조경면적 × 감축량 원단위
= 900m² × 0.015t/m² = 13.5tCO₂-eq`,
