    question: `온실가스 배출권의 할당, 조정 및 취소에 관한 지침에 의하면, "소규모 배출시설"이란 기준 연도 온실가스 배출량의 연평균 총량이 ( ① )인 배출시설을 말하며, "소량배출사업장"이란 기준연도 온실가스 배출량의 연평균 총량이 ( ② )인 사업장을 말한다.`,
