    no: 4,
    type: "서술",
    topic: "Scope 1·2·3",
    question: `Scope 1, 2, 3의 정의를 작성하시오.`,
    answer: `① Scope 1(직접배출원) : 직접적인 온실가스 배출로 기업이 직접 운영하고 통제하는 배출원에서 발생함(고정연소, 이동연소, 공정배출, 탈루배출로 구분됨)
② Scope 2(간접배출원) : 외부에서 생산된 전기나 열(스팀 등)이며, 기업이 사업장 외부에 있는 발전시설로부터 구입한 전력의 생산과정에서 배출된 온실가스가 해당됨
③ Scope 3(기타 간접배출원) : Scope 1, 2를 제외한 온실가스 배출활동, 기업의 폐기물 배출활동, 원·부자재 변경 등이 해당됨`,
    keywords: ["직접배출원", "간접배출원", "기타 간접배출원", "고정연소", "이동연소", "공정배출"],
    note: ""
