    exam: "2016년 4회",
    no: 10,
    type: "계산",
    topic: "활동자료(수송)",
    question: `다음 주어진 조건을 활용하여 활동자료를 산출하시오.
<table>
<tr><th>경유 차량의 주행거리</th><td>135,000km</td></tr>
<tr><th>경유 차량의 연비</th><td>9.33km/L</td></tr>
<tr><th>휘발유 차량의 주행거리</th><td>96,000km</td></tr>
<tr><th>휘발유 차량의 연비</th><td>12.4km/L</td></tr>
</table>`,
    answer: `주어진 조건들을 활용해서 구할 수 있는 활동자료는 연료사용량이다.
연료 사용량 = Σ (연료별 배출원별 주행거리(km) / 연료별 배출원별 연비(km/L))
경유 사용량 = 135,000km / 9.33km/L = 14,469.453L
휘발유 사용량 = 96,000km / 12.4km/L = 7,741.935L
∴ 경유 사용량 = 14,469.435L, 휘발유 사용량 = 7,741.935L`,
    keywords: ["주행거리", "연비", "14,469", "7,741.935"],
