    topic: "모니터링(유형 A-1)",
    question: `A-1 모니터링 유형을 도식하고 설명하여라.`,
    answer: `<img src="img/2016-4-13.jpg" alt="A-1 유형 모식도: 사업장 경계 안에서 공급 → WH → 배출시설">

A-1 유형은 연료 및 원료 공급자가 상거래 등을 목적으로 설치·관리하는 측정기기(WH)를 이용하여 연료사용량 등 활동자료를 수집하는 방법이다. 이는 주로 전력 및 열(증기), 도시가스를 구매하여 사용하는 경우 혹은 화석연료를 구매하여 단일 배출시설에 공급하는 경우에 적용할 수 있다.`,
