    topic: "폐기물 소각 Tier 1 산정식",
    question: `다음은 폐기물의 소각 부문 중 고상폐기물의 Tier 1 산정식이다. 이 중 dmᵢ, CFᵢ, FCFᵢ에 대하여 설명하시오.
CO₂ Emissions = Σᵢ (SWᵢ × dmᵢ × CFᵢ × FCFᵢ × OFᵢ) × 3.664`,
    answer: `CO₂ Emissions = Σᵢ (SWᵢ × dmᵢ × CFᵢ × FCFᵢ × OFᵢ) × 3.664
여기서, CO₂ Emissions : 폐기물 소각에서 발생되는 온실가스 양(tCO₂)
SWᵢ : 폐기물 성상(i)별 소각량(t-Waste)
dmᵢ : 폐기물 성상(i)별 건조물질 질량 분율(0에서 1사이의 소수)
CFᵢ : 폐기물 성상(i)별 탄소 함량(tC/t-Waste)
FCFᵢ : 화석탄소 질량 분율(0에서 1사이의 소수)
OFᵢ : 산화계수(소각효율, 0에서 1사이의 소수)
3.664 : CO₂의 분자량(44.010) / C의 원자량(12.011)`,
    keywords: ["dm", "CF", "FCF", "건조물질", "탄소 함량", "화석탄소"],
    note: ""
