    question: `모니터링 유형 중 A-4 모식도를 그리고 설명하시오.`,
    answer: `<img src="img/2017-2-08.jpg" alt="A-4 유형 모식도: 사업장 경계 안 WH → FL → 배출시설, 또 다른 FL → 타 사업장 경계">

A-4 유형은 연료나 원료 공급자가 상거래를 목적으로 설치·관리하는 측정기기(WH)와 주기적인 정도검사를 실시하는 내부 측정기기(FL)를 사용하며, 연료나 원료 일부를 파이프 등을 통해 연속적으로 외부 사업장이나 배출시설에 공급할 경우 활동자료를 결정하는 방법이다. 이 경우, 타사업장 공급 측정기기는 주기적인 정도검사를 실시하는 측정기기를 사용하여 활동자료를 수집하여야 하며, 사업장에서 조직경계 외부로 판매하거나 공급한 양을 제외하여 배출시설의 활동자료를 결정한다.`,
    keywords: ["A-4", "WH", "FL", "정도검사", "타사업장"],
    note: ""
