    answer: `순발열량은 일정단위의 연료가 완전연소되어 생기는 열량에서 연료 중 수증기의 잠열을 뺀 열량으로서 온실가스 배출량 산정에 활용되는 발열량을 말한다. 총발열량은 일정단위의 연료가 완전연소되어 생기는 열량(연료 중 수증기의 잠열까지 포함한다)으로서 에너지 사용량 산정에 활용된다.`,
