    answer: `LULUCF란 Land Use, Land-Use-Change, Forestry의 약자로, 토지이용, 토지용도의 변경, 임업의 결과로 온실가스를 제거하거나 상쇄하는 것을 의미한다. 1997년 교토의정서에서 채택된 용어이며, 온실가스의 배출 감축을 위한 방법으로 산림의 증대를 통해서 온실가스의 순감축을 할 수 있다는 논리이다. 산림과 토지를 흡수원(sink)으로 인정한 것이며 토지의 이용도 변화와 산림이 새로운 온실가스 감축수단으로 등장한 것이다.`,
