    topic: "역청·COG·BFG 정의",
    question: `다음 3가지 연료에 대한 세부적인 정의를 쓰시오. (단, 온실가스 배출권거래제 배출량 보고 및 인증에 관한 지침상 기재된 내용을 바탕으로 한다.)
① 역청(Bitumen)
② 코크스로 가스(Coke Oven Gas)
③ 고로 가스(Blast Furnace Gas)`,
    answer: `① 역청 : 콜로이드 구조(colloidal structure)이며 고체, 반고체의 점성을 가진 탄화수소를 말한다. 흑갈색 또는 갈색이며, 원유 증류에서의 잔여물, 상압 증류에서 오일 잔여물(oil residues)의 진공 증류로 얻어진다. 역청은 아스팔트(asphalt)로도 불리며 도로의 포장재 등으로 주로 이용된다.
② 코크스로 가스 : 철강의 생산을 위한 코크스로 코크스(coke oven coke) 제조 시 발생하는 부생가스이다.
③ 고로 가스 : 철강산업에서 용광로에서의 코크스의 연소 시 생산되는 부생가스이다.`,
