    question: `BAU에 대해 설명하시오.`,
    answer: `BAU는 Business As Usual의 약자로, 현재까지의 온실가스 감축정책 추세가 미래에도 지속된다는 가정하에 온실가스 감축 조치를 하지 않았을 경우 배출될 것으로 예상되는 미래 배출전망치(온실가스 배출량 추정값)이다. 우리나라는 2009년 국가 온실가스 배출량 목표로 2020년 BAU 대비 30% 감축을 공표하였으며, 2015년 국무회의에서는 2030년 BAU 대비 37% 감축을 목표로 결정하였다.`,
