    question: `신·재생에너지에는 신에너지와 재생에너지가 있다. 이에 대해 각각 설명하고, 각 에너지에 해당하는 종류를 3가지씩 쓰시오.`,
    answer: `1. 신에너지
① 정의 : 기존의 화석연료를 변환시켜 수소, 산소 등의 화학반응을 통해 전기 또는 열을 이용하는 에너지로, 3가지 종류가 있다.
② 종류 : 연료전지, 석탄 액화가스화, 수소에너지
2. 재생에너지
① 정의 : 햇빛, 물, 지열, 강수, 생물유기체 등을 포함하는 재생 가능한 에너지를 변환시켜 이용하는 에너지로, 8가지 종류가 있다.
② 종류 : 태양에너지, 풍력, 수력, 해양에너지, 지열에너지, 바이오에너지, 폐기물에너지, 그 밖에 석유·석탄·원자력 또는 천연가스가 아닌 에너지
※ 재생에너지 종류의 경우, 8가지 중 3가지만 작성한다.`,
