    type: "서술",
    topic: "연료전지 반응",
    question: `연료전지는 산화·환원 반응이 일어나는데, 양극과 음극에서 각각 어떤 반응이 일어나는지 서술하고 반응식도 함께 기재하시오.`,
    answer: `연료전지의 가장 전형적인 형태는 수소-산소 연료전지로, 수소와 산소의 반응을 통해 전기 및 열을 발생하는 전기화학적 장치이다.
H₂ + (1/2)O₂ → H₂O + 전기 및 열
수소를 이용한 연료전지의 원리는 외부의 공기가 음극과 접촉하는 과정에서 공기 중 산소가 산소이온으로 환원되어 전해물질(electrolyte)을 통과하여 양극으로 이동하고, 양극에서는 외부로부터 공급된 수소가 산화반응에 의해 수소이온으로 전환되며, 음극에서는 탄소극판에서 생성된 탄소와 수소이온이 반응하여 이산화탄소를 생성한다. 이러한 과정에서 양극에 생성된 전자는 전지의 이동을 차단하기 위해 인산 전해질을 통과하지 못하기 때문에 두 전극판을 연결한 전선을 통해 전류가 흘러 전기를 발생한다.`,
