    type: "서술",
    topic: "A사업장 Scope 구분",
    question: `A사업장은 석회를 생산하는 사업장으로, 주변 광산에서 채굴하여 원료를 공급하고 있다. 석회 생산공정에 의해 석회를 생산하고 있으며, 생산공정에서 폐기물이 발생되고, 외부 업체에 의해 폐기물 회수 및 재활용하고 있다. 이 사업장은 휘발유 차량 3대를 법인 명의로 보유하고 있고, 보일러로 LNG 1기, B-C유(벙커C유) 2기를 보유하고 있다. 또한, 사업장 내 소규모 폐수처리시설을 보유하고 있다. 이때, 이 사업장의 온실가스 배출원을 구분하고, 대상 온실가스 종류를 기술하시오.
<img src="img/2023-24-18.jpg" alt="A사업장 공정도: 석회석 혼합기 → 원료 분해기 → 원료 저장기 → 예열기 → 소성로 → 냉각기 → 시멘트 분쇄기, 소성로에서 폐기물 배출(외주업체 수거), 부속설비로 폐수처리시설·법인 소유 차량 3대·보일러(LNG) 1기·보일러(B-C유) 2기">`,
