    question: `인벤토리의 하향식 접근방법과 상향식 접근방법에 대해 설명하시오.`,
    answer: `① 하향식 접근방법(top-down) : 유사 배출원 또는 흡수원의 온실가스 배출량 또는 흡수량 산정을 위해 통합 활동자료(activity data)를 활용하고, 동일한 산정방법과 배출계수를 적용·산정하는 방식으로, 대부분의 국가 인벤토리와 지자체 인벤토리에서 사용한다.
② 상향식 접근방법(bottom-up) : 단위배출원의 배출특성 자료를 활용하여 배출량을 산정하고 이를 통합하여 배출 주체의 온실가스 인벤토리를 결정하는 방식으로, 단위배출원 또는 흡수원의 특성을 반영하여 온실가스 인벤토리를 산정하기 때문에 배출 주체의 정확한 인벤토리를 결정할 수 있는 장점을 가진다.`,
